{filters&&<div className="expanded-filters"><label>Cidade<Picker label="Filtrar por cidade" value={city} onChange={v=>{setCity(v);setExpanded(true);}} options={["Todas","Barro, CE","Brejo Santo, CE","Juazeiro do Norte, CE"]}/></label><label>Modalidade<Picker label="Filtrar por modalidade" value={mode} onChange={v=>{setMode(v);setExpanded(true);}} options={["Todas","Presencial","Remoto","Híbrido"]}/></label><label className="filter-search">Cargo ou competência<input placeholder="Ex.: redes, vendas, Excel" aria-label="Filtrar por cargo ou competência" value={query} onChange={e=>{setQuery(e.target.value);setExpanded(true);}}/></label><button className="text-link" onClick={()=>{setQuery("");setCity("Todas");setMode("Todas");setArea("Todas as áreas");}}>Limpar filtros</button></div>}
