{[{n:"01",category:"TECNOLOGIA",title:"Habilidades para um mundo digital",source:"Escola do Trabalhador 4.0",desc:"Tecnologia e produtividade para acompanhar as mudanças no trabalho.",icon:Monitor,link:"https://www.gov.br/trabalho-e-emprego/pt-br/servicos/trabalhador/qualificacao-profissional/caminho-digital",color:"aqua"},{n:"02",category:"DESENVOLVIMENTO",title:"Conhecimento que vira oportunidade",source:"Fundação Bradesco",desc:"Aprenda sobre negócios, tecnologia e desenvolvimento profissional.",icon:BookOpen,link:"https://www.ev.org.br/cursos",color:"sand"},{n:"03",category:"EMPREENDEDORISMO",title:"Tire suas ideias do papel",source:"Sebrae",desc:"Cursos para melhorar seu atendimento, organizar e desenvolver seu negócio.",icon:BriefcaseBusiness,link:"https://loja.sebrae.com.br/cursos/cursos-online",color:"ice"}].map(c=><article className={"course-card "+c.color} key={c.n}><div className="course-art"><c.icon size={40} strokeWidth={1.25}/><span>{c.n}</span></div><div className="course-body"><div className="course-kicker">{c.category}<span>Gratuito</span></div><h3>{c.title}</h3><p>{c.desc}</p><div className="course-provider">{c.source}</div><a href={c.link} target="_blank" rel="noopener noreferrer">Explorar cursos <ArrowUpRight size={19}/></a></div></article>)}
